const reloadCard = async (key: string): Promise<void> => {
    const item = itemsRef.current.find((i) => i.key === key)
    if (!item) return
    const target = ++versionOf(item).wanted
    const against = bodyAgainst(viewOfRef(item))
    const diff = await diffFor(item, against)
    patchSection(key, { status: 'loaded', diff, error: undefined, revision: (sectionsRef.current[key]?.revision ?? 0) + 1, against, signature: item.signature })
    const version = versionOf(item)
    version.loaded = Math.max(version.loaded, target)
    catchUp(key)
  }

const diffFor = (item: ReviewItem, against: 'base' | 'reviewed') => {
    const activeScope = scopeRef.current
    const currentCommit = commitRef.current
    if (activeScope !== null && 'commit' in activeScope && currentCommit) {
      return fetchDiff(context, worktree, { path: item.path, source: 'commit', oldPath: item.oldPath, commit: currentCommit.commit })
    }
    if (activeScope !== null && 'source' in activeScope) {
      return fetchDiff(context, worktree, { path: item.path, source: activeScope.source, oldPath: item.oldPath })
    }
    return fetchDiff(context, worktree, { path: item.path, source: 'review', oldPath: item.oldPath, against })
  }

export async function fetchDiff(context: UiPluginContext, worktree: string, request: DiffRequest): Promise<GitDiff> {
  const { path, source, oldPath, commit, against } = request
  return (await context.call('quirky.git/diff', {
    worktree,
    path,
    source,
    ...(oldPath ? { oldPath } : {}),
    ...(commit ? { commit } : {}),
    ...(against ? { against } : {})
  })) as GitDiff
}

